tasks.starter:
def attention_investigation(q,k,v,temperatures,mask=None):
    """Inputs q:[Nq,d], k:[Nk,d], v:[Nk,d_v] are 2-D floating Torch tensors. temperatures is a nonempty sequence of positive scalars. mask is None or a Boolean tensor broadcastable to [Nq,Nk]: True ALLOWS a key (the opposite of torch MultiheadAttention blocking-mask semantics). Invalid tensor dimensions, mismatched widths/counts, nonpositive temperature or a query with no allowed key must raise ValueError. Return a list in temperature order of dictionaries with keys temperature (float), weights ([Nq,Nk] tensor), output ([Nq,d_v] tensor), entropy (float, mean over queries of natural-log entropy)."""
    raise NotImplementedError

tasks.solution:
def attention_investigation(q,k,v,temperatures,mask=None):
    if q.ndim!=2 or k.ndim!=2 or v.ndim!=2:
        raise ValueError('expected two-dimensional tensors')
    if q.shape[-1]!=k.shape[-1] or k.shape[-2]!=v.shape[-2]:
        raise ValueError('incompatible feature or token dimensions')
    scores=q@k.transpose(-2,-1)/np.sqrt(q.shape[-1])
    if mask is not None:
        mask=torch.broadcast_to(mask.bool(),scores.shape)
        if not bool(mask.any(-1).all()):
            raise ValueError('every query must retain a key')
    if len(temperatures)==0:raise ValueError("no temperatures")
    result=[]
    for temperature in temperatures:
        if temperature<=0:
            raise ValueError('temperature must be positive')
        scaled=scores/temperature
        if mask is not None:
            scaled=scaled.masked_fill(~mask,float('-inf'))
        weights=scaled.softmax(-1)
        entropy=-(weights*weights.clamp_min(1e-30).log()).sum(-1).mean()
        result.append({'temperature':temperature,'weights':weights,'output':weights@v,'entropy':float(entropy)})
    return result
